param(
    [string]$RepoRoot = "."
)

$ErrorActionPreference = "Stop"
$RepoRoot = (Resolve-Path $RepoRoot).Path

Write-Host "== DepLoom BLOCK 4 FINAL: global exact coordinator + certified graph generalization =="
Write-Host "Exact base: 9bfd3acef70ddc3b0728f12b36abd87d5efd3316"
Write-Host "Safety: 15-anchor preflight + sandbox targeted/full Python tests before real checkout."

$payload = @'

'@

$tempPy = Join-Path ([System.IO.Path]::GetTempPath()) ("deploom-block4-" + [guid]::NewGuid().ToString("N") + ".py")
$dryRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("deploom-block4-dry-" + [guid]::NewGuid().ToString("N"))
$dryAdded = $false

try {
    [System.IO.File]::WriteAllBytes($tempPy, [Convert]::FromBase64String($payload.Trim()))

    Push-Location $RepoRoot
    try {
        $head = (git rev-parse HEAD).Trim()
        if ($head -ne "9bfd3acef70ddc3b0728f12b36abd87d5efd3316") {
            throw "BLOCK 4 requires exact master 9bfd3acef70ddc3b0728f12b36abd87d5efd3316, current HEAD=$head"
        }
        if (git status --porcelain --untracked-files=no) {
            throw "BLOCK 4 requires a clean tracked working tree"
        }
        git worktree add --quiet --detach $dryRoot HEAD
        if ($LASTEXITCODE -ne 0) { throw "Could not create BLOCK 4 sandbox worktree" }
        $dryAdded = $true
    }
    finally {
        Pop-Location
    }

    Write-Host ""
    Write-Host "== Sandbox transform =="
    python $tempPy $dryRoot
    if ($LASTEXITCODE -ne 0) { throw "BLOCK 4 sandbox transform failed; real checkout untouched" }

    Push-Location $dryRoot
    try {
        python -m py_compile `
          .\constraint_verify.py `
          .\dependency_live_roadmap_generator.py `
          .\tests\test_constraint_verify.py `
          .\tests\test_baseline_localization_contract.py
        if ($LASTEXITCODE -ne 0) { throw "BLOCK 4 sandbox syntax validation failed" }

        Write-Host ""
        Write-Host "== Sandbox targeted tests =="
        python -m unittest `
          tests.test_constraint_verify `
          tests.test_baseline_localization_contract `
          tests.test_verification_proof `
          tests.test_baseline_constraint_verifier -v
        if ($LASTEXITCODE -ne 0) { throw "BLOCK 4 sandbox targeted tests failed; real checkout untouched" }

        Write-Host ""
        Write-Host "== Sandbox full Python suite =="
        python .\run_tool_tests.py --suite all
        if ($LASTEXITCODE -ne 0) { throw "BLOCK 4 sandbox full Python suite failed; real checkout untouched" }

        git diff --check
        if ($LASTEXITCODE -ne 0) { throw "BLOCK 4 sandbox git diff --check failed" }
    }
    finally {
        Pop-Location
    }

    Write-Host "Sandbox BLOCK 4: PASS"

    Push-Location $RepoRoot
    try {
        git worktree remove --force $dryRoot
        if ($LASTEXITCODE -ne 0) { throw "Could not remove BLOCK 4 sandbox worktree" }
        $dryAdded = $false
    }
    finally {
        Pop-Location
    }

    Write-Host ""
    Write-Host "== Applying BLOCK 4 to real checkout =="
    python $tempPy $RepoRoot
    if ($LASTEXITCODE -ne 0) { throw "BLOCK 4 real transform failed" }

    Push-Location $RepoRoot
    try {
        Write-Host ""
        Write-Host "== Desktop contracts =="
        Push-Location ".\desktop"
        try {
            npm run lint
            if ($LASTEXITCODE -ne 0) { throw "Desktop lint failed" }
            npm run build
            if ($LASTEXITCODE -ne 0) { throw "Desktop build failed" }
            npm run check:cross-platform
            if ($LASTEXITCODE -ne 0) { throw "Cross-platform check failed" }
            npm run check:migration-progress
            if ($LASTEXITCODE -ne 0) { throw "Migration progress check failed" }
            npm run check:log-presentation
            if ($LASTEXITCODE -ne 0) { throw "Log presentation check failed" }
        }
        finally {
            Pop-Location
        }

        git diff --check
        if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }

        Write-Host ""
        Write-Host "== Public sanitization (informational here) =="
        python .\scripts\check-public-sanitization.py
        if ($LASTEXITCODE -ne 0) {
            Write-Warning "Public sanitization remains a separate release gate; BLOCK 4 changes are not rolled back."
        }

        Write-Host ""
        Write-Host "== BLOCK 4 FINAL result =="
        git status --short
        Write-Host ""
        Write-Host "Authority model:"
        Write-Host "  HARD_MODEL            metadata/peer constraints"
        Write-Host "  CONFIRMED_CONSTRAINT  freshly certified dynamic incompatibility"
        Write-Host "  DIAGNOSTIC_HINT       graph/signature proposal only"
        Write-Host "  NAVIGATION_ONLY       search/coordinator state only"
        Write-Host ""
        Write-Host "Exact assignment failures now use global exclusions without component merge."
        Write-Host "Blind ddmin is no longer mandatory on the production hard-failure path."
    }
    finally {
        Pop-Location
    }
}
finally {
    if ($dryAdded) {
        Push-Location $RepoRoot
        try { git worktree remove --force $dryRoot 2>$null | Out-Null } finally { Pop-Location }
    }
    elseif (Test-Path $dryRoot) {
        Remove-Item $dryRoot -Recurse -Force -ErrorAction SilentlyContinue
    }
    Remove-Item $tempPy -Force -ErrorAction SilentlyContinue
}
